def _segments(text, spans):
    out=[]
    for s in spans:
        if isinstance(s,str): out.append(s)
        elif isinstance(s,dict):
            if "text" in s: out.append(str(s.get("text","")))
            else:
                a=int(s.get("start",s.get("begin",0))); b=int(s.get("end",s.get("stop",a)))
                out.append(text[a:b])
        elif isinstance(s,(list,tuple)) and len(s)>=2: out.append(text[int(s[0]):int(s[1])])
        else: out.append("")
    return out

def _has(s, words):
    return any(w in s for w in words)

def _item(s):
    q=s.strip()
    return q.startswith("(") or (len(q)>1 and q[0].isalnum() and q[1] in (".",")"))

def _lead(out,xs,i,words,n=7):
    for j in reversed(range(max(0,i-n),i)):
        if _has(xs[j],words):
            out.add(j); return

def _defs(out,xs,i,n=20):
    for j in range(max(0,i-n),i+1):
        q=xs[j]
        if _has(q,("confidential information means","confidential information shall mean","proprietary information shall mean","evaluation material means","protectable interests” means","protectable interests means")):
            out.add(j)

def _following(out,xs,i,words,n=4):
    for j in range(i+1,min(len(xs),i+n+1)):
        if _has(xs[j],words): out.add(j)
        elif not _item(xs[j]): break

def propose_members(text, spans, public_hypothesis_key):
    xs=[s.lower() for s in _segments(text,spans)]; out=set(); k=public_hypothesis_key
    for i,s in enumerate(xs):
        if k=="nda-11":
            if _has(s,("reverse engineer","reverse-engineer","decompile","disassemble")):
                out.add(i); _lead(out,xs,i,("agrees:","undertakes:","shall:"),5)
        elif k=="nda-16":
            if _has(s,("return","destroy","delete","erase","deliver up","surrender")) and _has(s,("confidential","proprietary","information","data","material","document","copies","records")):
                out.add(i); _following(out,xs,i,("termination","expiration","completion","conclusion","ceasing","not wish to proceed","not consummated","assessment period","end of employment"),4)
            elif _has(s,("termination","expiration","completion","conclusion","ceasing","not wish to proceed","not consummated","assessment period","end of employment")):
                _lead(out,xs,i,("return","destroy","delete","erase","deliver up","surrender"),4)
        elif k=="nda-15":
            if _has(s,("no license","no licence","no right","no rights","does not acquire","does not grant","not be construed as granting","remain the property","property of the disclos","property of owner","exclusive property","sole property","exclusive owner","exclusive title","retain all rights","reserves all rights","no title","no interest","proprietary of the disclos","intellectual property protection")):
                out.add(i)
        elif k=="nda-10":
            if _has(s,("existence of this agreement","existence and terms","existence or contents","fact that discussions","discussions or negotiations","discussions and negotiations","fact that information has been","subject matter or terms","public announcement concerning this agreement","terms of this agreement are confidential","agreement is confidential","existence and content of the discussions")):
                out.add(i); _defs(out,xs,i)
        elif k=="nda-2":
            subjects=("business","financial","commercial","marketing","customer","client","supplier","employee","personnel","staff","operational","contractual","business plans","non-technical","all information","all trade secrets","agreements","sales","distribution","costs")
            if _has(s,subjects) and _has(s,("confidential information","proprietary information","evaluation material","information shall","information means","shall include","including","protectable interests")):
                out.add(i); _defs(out,xs,i)
            elif _item(s) and _has(s,subjects):
                for j in reversed(range(max(0,i-18),i)):
                    if _has(xs[j],("confidential information means","proprietary information shall mean","evaluation material means","protectable interests” means","protectable interests means","including, without limiting")):
                        out.update((j,i)); break
        elif k=="nda-1":
            if _has(s,("marked","mark or label","designated","identified as","identified at","identify it in writing","reasonable person","reasonably understood","circumstances of disclosure","nature of the information","whether or not","need not be marked","does not need to be marked","regardless of form","specifically stated otherwise")) and _has(s,("confidential","proprietary","information","disclos")):
                out.add(i); _defs(out,xs,i)
        elif k=="nda-19":
            if _has(s,("shall survive","will survive","survive termination","survive expiration","continue to be bound","continue in force","continue to apply","remain in effect","notwithstanding the return","notwithstanding such return","after termination","beyond termination","continue beyond termination","remain binding and enforceable after","indefinite confidentiality obligation","notwithstanding the termination")):
                out.add(i)
                if _has(s,("notwithstanding the termination","notwithstanding termination")):
                    for j in range(i+1,min(len(xs),i+4)):
                        if _item(xs[j]): out.add(j)
                        else: break
        elif k in ("nda-12","nda-13"):
            words=("independently developed","independent development","developed independently","independently derived","developing information internally","independently create","right to independently develop") if k=="nda-12" else ("from a third party","from third parties","third party having","third party who","another source","independent source","source other than","obtained from others","received from an independent","lawfully obtained from a third party","rightfully disclosed to it by a third party")
            if _has(s,words):
                out.add(i); _lead(out,xs,i,("shall not include","does not include","shall exclude","shall not apply","restrictions","obligations","exceptions","excludes","inoperative","will not apply","foregoing shall not apply"),9)
        elif k=="nda-20":
            if _has(s,("retain","retained","keep one","archiv","back-up","backup","not required to erase","not required to delete","retaining no copies","without retaining","shall not retain","infeasible","return","destroy","surrender")) and _has(s,("confidential","proprietary","information","data","material","copies","documents","records","property")):
                out.add(i); _lead(out,xs,i,("notwithstanding","return of","return or destruction","documents or records"),4)
        elif k=="nda-3":
            if _has(s,("oral","orally","verbally","uttered","spoken","heard","regardless of form","whatever form","any form whatsoever","form or medium","however recorded","intangible form")) and _has(s,("information","disclos","communicat","confidential")):
                out.add(i); _defs(out,xs,i); _lead(out,xs,i,("deemed to be confidential information","confidential information means"),5)
        elif k=="nda-18":
            if _has(s,("solicit","induce","entice","offer employment","offer to hire","employ or retain","contract for the services")) and _has(s,("shall not","will not","agrees that","restriction period","following termination","without the prior written consent")): out.add(i)
        elif k in ("nda-7","nda-5"):
            classes=("employee","personnel","staff member") if k=="nda-5" else ("agent","consultant","advisor","adviser","counsel","accountant","contractor","subcontractor","representative","third party","professional adviser")
            if _has(s,classes) and _has(s,("disclose","disclosure","access","furnish","provide","share","need to know","only to","may disclose","shall not disclose","not disclose")):
                out.add(i); _lead(out,xs,i,("undertakes that","agrees:","shall:","without the prior written consent"),3)
        elif k=="nda-17":
            if _has(s,("make copies","create copies","shall not copy","not copy","not reproduce","copy or reproduce","copies required","copying","duplicate","reduce to writing","photocopying","reproduce in any form")) and _has(s,("confidential","information","data","material","document")):
                out.add(i); _lead(out,xs,i,("undertakes that","agrees:","shall:","documents or records"),3)
        elif k=="nda-8":
            legal=_has(s,("required by law","required to disclose","legally compelled","court order","subpoena","legal process","governmental authority","government regulations","applicable law","applicable laws","regulatory authority","operation of law","judicial proceeding","administrative proceeding"))
            notice=_has(s,("notice","notify","consult","inform","advise"))
            if legal or notice:
                for j in range(max(0,i-3),min(len(xs),i+4)):
                    if legal and _has(xs[j],("notice","notify","consult","inform","advise")): out.update((i,j))
                    if notice and _has(xs[j],("required by law","required to disclose","legally compelled","court order","subpoena","legal process","governmental","regulatory","applicable law")): out.update((i,j))
                if out: _lead(out,xs,i,("shall not include","does not include","shall not apply","restrictions","obligations","exceptions"),7)
        elif k=="nda-4":
            if _has(s,("solely for","only for","no purpose other","not use","use only","except for the purpose","necessary for the purpose","use the information for","not to utilise","not to utilize","sole purpose")) and _has(s,("confidential","information","data","material","purpose","evaluation","project")):
                out.add(i); _lead(out,xs,i,("agrees:","undertakes that","shall:","without the prior written consent"),4)
    return sorted(out)
